function txDone(tx) {
  return new Promise(function(resolve, reject) {
    tx.oncomplete = function() { resolve(); };
    tx.onerror = function() { reject(tx.error); };
  });
}
async function storeAll(name) {
  const db = await openDb();
  return new Promise(function(resolve, reject) {
    const tx = db.transaction(name, "readonly");
    const req = tx.objectStore(name).getAll();
    req.onsuccess = function() { resolve(req.result || []); };
    req.onerror = function() { reject(req.error); };
  });
}
async function storePut(name, item) {
  const db = await openDb();
  const tx = db.transaction(name, "readwrite");
  tx.objectStore(name).put(item);
  await txDone(tx);
}
async function storeDel(name, id) {
  const db = await openDb();
  const tx = db.transaction(name, "readwrite");
  tx.objectStore(name).delete(id);
  await txDone(tx);
}
async function purgeExpiredTrash() {
  const items = await storeAll("trash");
  const now = Date.now();
  for (const it of items) {
    if (now - (it.trashedAt || 0) > TRASH_MS) await storeDel("trash", it.id);
  }
}

async function api(path, body) {
  var headers = authHeaders();
  if (body) headers["Content-Type"] = "application/json";
  const res = await fetch(qs(path), {
    method: body ? "POST" : "GET",
    headers: headers,
    body: body ? JSON.stringify(body) : undefined,
    cache: "no-store",
    credentials: "omit",
  });
  const data = await res.json().catch(function() { return {}; });
  if (!res.ok || data.ok === false) throw new Error(data.error || ("HTTP " + res.status));
  return data;
}

function fillNotebooks(list, defaultId) {
  const sel = document.getElementById("nb");
  if (!sel) return;
  var prev = selectedNb || defaultId || "";
  sel.innerHTML = "";
  list = list || [];
  if (!list.length) {
    const o = document.createElement("option");
    o.value = ""; o.textContent = "\uFF08\u7535\u8111\u4E0A\u8FD8\u6CA1\u6709\u8BB0\u5F55\u672C\uFF0C\u8BF7\u5148\u65B0\u5EFA\uFF09";
    sel.appendChild(o);
    selectedNb = "";
    return;
  }
  var hasPrev = false;
  list.forEach(function(n) {
    const o = document.createElement("option");
    o.value = n.id; o.textContent = n.name;
    sel.appendChild(o);
    if (n.id === prev) hasPrev = true;
  });
  selectedNb = hasPrev ? prev : (defaultId || list[0].id);
  sel.value = selectedNb;
  sel.onchange = function() {
    selectedNb = sel.value;
    if (lanOk && selectedNb) {
      api("/api/notebook", { notebook_id: selectedNb }).catch(function(){});
    }
  };
}

function setLan(ok, detail) {
  lanOk = !!ok;
  const pill = document.getElementById("lanPill");
  if (!pill) return;
  if (ok) {
    pill.textContent = "\u5DF2\u8FDE\u63A5\u7535\u8111";
    pill.className = "lan-pill lan-on";
  } else {
    pill.textContent = detail ? ("\u672A\u8FDE\u901A \xB7 " + detail) : "\u672A\u8FDE\u7535\u8111 \xB7 \u4EC5\u672C\u5730\u7F13\u5B58";
    pill.className = "lan-pill lan-off";
  }
  var qw = document.getElementById("queueWarn");
  if (qw) {
    if (ok) {
      if (window.__sendPipe && window.__sendPipe.running) {
        qw.textContent = "\u53D1\u9001\u8FDB\u884C\u4E2D\uFF1A\u53EF\u7EE7\u7EED\u52FE\u9009\u672A\u53D1\u9001\u9879\u8FFD\u52A0\u961F\u5217\uFF1B\u53D1\u9001\u4E2D/\u6392\u961F\u4E2D\u6761\u76EE\u4E0D\u53EF\u52FE\u9009\u3002";
      } else {
        qw.textContent = "\u53EF\u52FE\u9009\u540E\u53D1\u9001\u5230\u7535\u8111\u3002\u53D1\u9001\u4E2D\u4ECD\u53EF\u8FFD\u52A0\u65B0\u52FE\u9009\u3002";
      }
    } else {
      qw.textContent =
        "\u5F53\u524D\u65E0\u6CD5\u8FDE\u4E0A\u7535\u8111\u670D\u52A1\u3002\u5185\u5BB9\u53EF\u5148\u300C\u52A0\u5165\u5F85\u53D1\u9001\u300D\u3002\u8BF7\u786E\u8BA4\uFF1A\u540C\u4E00 Wi\u2011Fi\u3001\u7535\u8111 Obsidian \u5F00\u7740\u3001\u624B\u673A\u5165\u53E3\u8FD0\u884C\u4E2D\u3001\u94FE\u63A5\u5E26 ?t= \u4EE4\u724C\u3002";
    }
  }
}

function authHeaders() {
  var h = {};
  var tok = TOKEN;
  try {
    if (!tok) tok = new URLSearchParams(location.search).get("t") || "";
  } catch (e) {}
  if (tok) h["X-Bridge-Token"] = tok;
  return h;
}

/** Low-level GET with timeout; returns { ok, status, data, error } */
function probeGet(path, timeoutMs) {
  timeoutMs = timeoutMs || 4000;
  return new Promise(function(resolve) {
    var done = false;
    var timer = setTimeout(function() {
      if (done) return;
      done = true;
      resolve({ ok: false, status: 0, data: {}, error: "\u8D85\u65F6" });
    }, timeoutMs);
    var opts = {
      method: "GET",
      headers: authHeaders(),
      cache: "no-store",
      credentials: "omit",
    };
    // Prefer not using AbortController on flaky mobile WebViews; use timeout race instead
    fetch(qs(path), opts).then(function(res) {
      return res.json().catch(function() { return {}; }).then(function(data) {
        if (done) return;
        done = true;
        clearTimeout(timer);
        resolve({
          ok: res.ok && data && data.ok !== false,
          status: res.status,
          data: data || {},
          error: (!res.ok || (data && data.ok === false))
            ? ((data && data.error) || ("HTTP " + res.status))
            : "",
        });
      });
    }).catch(function(e) {
      if (done) return;
      done = true;
      clearTimeout(timer);
      var msg = String(e && e.message || e || "\u7F51\u7EDC\u9519\u8BEF");
      if (msg.indexOf("Failed to fetch") >= 0 || msg.indexOf("NetworkError") >= 0) {
        msg = "\u65E0\u6CD5\u8BBF\u95EE\u7535\u8111\u670D\u52A1";
      }
      resolve({ ok: false, status: 0, data: {}, error: msg });
    });
  });
}

async function refreshLan() {
  // CRITICAL: if this HTML was served by the desktop bridge, we are already connected.
  // Never leave the pill stuck on "\u68C0\u6D4B\u7F51\u7EDC\u2026" \u2014 mark connected first, then refine via API.
  var host = "";
  try { host = location.hostname || ""; } catch (e) {}
  var hasTok = !!(TOKEN || ((location.search || "").indexOf("t=") >= 0));
  var pageFromBridge =
    (location.protocol === "http:" || location.protocol === "https:") &&
    hasTok &&
    host.length > 0;

  if (pageFromBridge && !lanOk) {
    // Optimistic: page load already proved the phone can reach the computer
    setLan(true);
    try {
      if (NOTEBOOKS && NOTEBOOKS.length) fillNotebooks(NOTEBOOKS, DEFAULT_NB);
    } catch (e0) {}
  }

  try {
    var r = await probeGet("/api/ping", 3500);
    if (!r.ok) r = await probeGet("/api/status", 3500);
    if (r.ok) {
      setLan(true);
      try {
        if (r.data && r.data.notebooks && r.data.notebooks.length) {
          fillNotebooks(r.data.notebooks, r.data.notebookId || DEFAULT_NB);
        } else if (NOTEBOOKS && NOTEBOOKS.length) {
          fillNotebooks(NOTEBOOKS, DEFAULT_NB);
        }
      } catch (e1) {}
      return;
    }
    // API failed but page was served by bridge \u2014 stay connected (don't flip to red)
    if (pageFromBridge) {
      setLan(true);
      var pill = document.getElementById("lanPill");
      if (pill) {
        pill.textContent = "\u5DF2\u8FDE\u63A5\u7535\u8111\uFF08\u9875\u9762\u53EF\u8FBE\uFF09";
        pill.className = "lan-pill lan-on";
      }
      return;
    }
    setLan(false, (r.error || "\u68C0\u6D4B\u5931\u8D25").toString().slice(0, 48));
  } catch (e) {
    if (pageFromBridge) {
      setLan(true);
      return;
    }
    setLan(false, String(e && e.message || e || "\u672A\u77E5\u9519\u8BEF").slice(0, 48));
  }
}

function switchTab(name) {
  ["compose","queue","trash","recent"].forEach(function(t) {
    document.getElementById("tab-" + t).classList.toggle("hidden", t !== name);
  });
  document.querySelectorAll(".tabs button").forEach(function(b) {
    b.classList.toggle("active", b.getAttribute("data-tab") === name);
  });
  if (name === "queue") renderQueue();
  if (name === "trash") renderTrash();
  if (name === "recent") refreshRecent();
}
document.querySelectorAll(".tabs button").forEach(function(b) {
  b.onclick = function() { switchTab(b.getAttribute("data-tab")); };
});

async function addQueueItem(item) {
  item.id = item.id || uid();
  item.createdAt = item.createdAt || Date.now();
  item.notebook_id = item.notebook_id || selectedNb || "";
  await storePut("queue", item);
  setStatus("\u5DF2\u52A0\u5165\u5F85\u53D1\u9001\uFF08\u672C\u5730\u7F13\u5B58\uFF09", "ok");
  renderQueue();
}

document.getElementById("btnCache").onclick = async function() {
  const text = document.getElementById("text").value.trim();
  if (!text) return setStatus("\u8BF7\u5148\u8F93\u5165\u5185\u5BB9", "err");
  await addQueueItem({ type: "text", text: text, organize: true, title: text.split("\\n")[0].slice(0, 40) });
  document.getElementById("text").value = "";
};

document.getElementById("btnSendNow").onclick = async function() {
  const text = document.getElementById("text").value.trim();
  if (!text) return setStatus("\u8BF7\u5148\u8F93\u5165\u5185\u5BB9", "err");
  if (!lanOk) {
    await addQueueItem({ type: "text", text: text, organize: true, title: text.split("\\n")[0].slice(0, 40) });
    setStatus("\u672A\u8FDE\u5C40\u57DF\u7F51\uFF1A\u5DF2\u7F13\u5B58\u5230\u5F85\u53D1\u9001", "err");
    return;
  }
  setStatus("\u53D1\u9001\u5E76\u6574\u7406\u4E2D\u2026");
  try {
    const r = await api("/api/text", { text: text, organize: true, source: "mobile-web", notebook_id: selectedNb, capturedAt: Date.now() });
    setStatus("\u5DF2\u5199\u5165\uFF1A" + (r.title || r.path || "ok") + (r.organized ? "\uFF08\u5DF2 AI \u6574\u7406\uFF09" : ""), "ok");
    document.getElementById("text").value = "";
    refreshRecent();
  } catch (e) {
    await addQueueItem({ type: "text", text: text, organize: true, title: text.split("\\n")[0].slice(0, 40) });
    setStatus("\u53D1\u9001\u5931\u8D25\uFF0C\u5DF2\u6539\u5B58\u5F85\u53D1\u9001\uFF1A" + (e.message || e), "err");
  }
};

document.getElementById("btnInbox").onclick = async function() {
  const text = document.getElementById("text").value.trim();
  if (!text) return setStatus("\u8BF7\u5148\u8F93\u5165\u5185\u5BB9", "err");
  if (!lanOk) {
    await addQueueItem({ type: "text", text: text, organize: false, title: text.split("\\n")[0].slice(0, 40) });
    setStatus("\u672A\u8FDE\u5C40\u57DF\u7F51\uFF1A\u5DF2\u7F13\u5B58\uFF08\u4EC5\u6536\u4EF6\u7BB1\u6A21\u5F0F\uFF09", "err");
    return;
  }
  setStatus("\u5199\u5165\u6536\u4EF6\u7BB1\u2026");
  try {
    const r = await api("/api/text", { text: text, organize: false, source: "mobile-web", notebook_id: selectedNb, capturedAt: Date.now() });
    setStatus("\u5DF2\u8FDB\u6536\u4EF6\u7BB1\uFF1A" + (r.path || "ok"), "ok");
    document.getElementById("text").value = "";
    refreshRecent();
  } catch (e) {
    setStatus(String(e.message || e), "err");
  }
};

function blobToBase64(blob) {
  return new Promise(function(resolve, reject) {
    const fr = new FileReader();
    fr.onload = function() {
      const s = String(fr.result || "");
      const i = s.indexOf(",");
      resolve(i >= 0 ? s.slice(i + 1) : s);
    };
    fr.onerror = reject;
    fr.readAsDataURL(blob);
  });
}

async function sendOne(it) {
  var capturedAt = it.createdAt || it.capturedAt || Date.now();
  if (it.type === "text") {
    return api("/api/text", {
      text: it.text,
      organize: it.organize !== false,
      source: "mobile-web-queue",
      notebook_id: it.notebook_id || selectedNb,
      capturedAt: capturedAt,
      createdAt: capturedAt,
    });
  }
  if (it.type === "voice") {
    return api("/api/voice", {
      audioBase64: it.audioBase64,
      mimeType: it.mimeType || "audio/wav",
      organize: true,
      source: "mobile-web-voice-queue",
      notebook_id: it.notebook_id || selectedNb,
      capturedAt: capturedAt,
      createdAt: capturedAt,
    });
  }
  if (it.type === "file") {
    return api("/api/file", {
      fileBase64: it.fileBase64,
      fileName: it.fileName,
      mimeType: it.mimeType,
      title: it.title,
      notebook_id: it.notebook_id || selectedNb,
      capturedAt: capturedAt,
      createdAt: capturedAt,
    });
  }
  throw new Error("unknown type");
}

async function sendIds(ids) {
  if (!lanOk) {
    setStatus("\u672A\u8FDE\u5C40\u57DF\u7F51\uFF0C\u65E0\u6CD5\u53D1\u9001", "err");
    return;
  }
  var added = enqueueSend(ids || []);
  if (!added) {
    setStatus(window.__sendPipe && window.__sendPipe.running
      ? "\u6240\u9009\u6761\u76EE\u5DF2\u5728\u53D1\u9001\u961F\u5217\u4E2D"
      : "\u6CA1\u6709\u53EF\u53D1\u9001\u7684\u5185\u5BB9\uFF08\u6392\u961F\u4E2D/\u53D1\u9001\u4E2D\u8BF7\u7528\u53D6\u6D88\uFF09", "err");
    return;
  }
  if (window.__sendPipe && window.__sendPipe.running) {
    setStatus("\u5DF2\u8FFD\u52A0 " + added + " \u6761\u5230\u53D1\u9001\u961F\u5217", "ok");
    renderQueue();
    updateSendProgressUi();
  } else {
    setStatus("\u5F00\u59CB\u53D1\u9001\uFF08\u53EF\u8FFD\u52A0\uFF1B\u53EF\u52FE\u9009\u53D6\u6D88\u6392\u961F\uFF09\u2026", "ok");
  }
  void pumpSend();
}

function ensureSendPipe() {
  if (!window.__sendPipe) {
    window.__sendPipe = {
      running: false,
      pending: [],
      activeId: null,
      cancelled: {},
      done: 0,
      ok: 0,
      fail: 0,
      cancelledCount: 0,
      t0: 0,
    };
  }
  return window.__sendPipe;
}

function isInSendPipeline(id) {
  var p = window.__sendPipe;
  if (!p || !id) return false;
  if (p.activeId === id) return true;
  return p.pending.indexOf(id) >= 0;
}

function enqueueSend(ids) {
  var p = ensureSendPipe();
  var n = 0;
  (ids || []).forEach(function(id) {
    if (!id) return;
    if (p.activeId === id) return;
    if (p.pending.indexOf(id) >= 0) return;
    if (p.cancelled[id]) delete p.cancelled[id];
    p.pending.push(id);
    n++;
  });
  return n;
}

function pipelineTotal(p) {
  return p.done + p.pending.length + (p.activeId ? 1 : 0);
}

function updateSendProgressUi(extraLabel, indeterminate, state) {
  var p = ensureSendPipe();
  var total = pipelineTotal(p);
  var done = p.done;
  var label = extraLabel;
  if (!label) {
    if (p.running) {
      var eta = "";
      if (p.done > 0 && total > p.done) {
        var elapsed = (Date.now() - p.t0) / 1000;
        var per = elapsed / Math.max(p.done, 1);
        var left = Math.ceil(per * (total - p.done));
        eta = " \xB7 \u7EA6\u5269 " + left + " \u79D2";
      }
      label = "\u8FDB\u5EA6 " + done + "/" + total +
        "\uFF08\u6210\u529F " + p.ok +
        (p.fail ? " / \u5931\u8D25 " + p.fail : "") +
        (p.cancelledCount ? " / \u53D6\u6D88 " + p.cancelledCount : "") +
        "\uFF09" + eta;
    } else {
      label = "\u53D1\u9001\u5B8C\u6210\uFF1A\u6210\u529F " + p.ok +
        (p.fail ? "\uFF0C\u5931\u8D25 " + p.fail : "") +
        (p.cancelledCount ? "\uFF0C\u53D6\u6D88 " + p.cancelledCount : "");
    }
  }
  showSendProgress(done, Math.max(total, 1), label, !!indeterminate, state);
}

async function pumpSend() {
  var p = ensureSendPipe();
  if (p.running) return;
  if (!lanOk) {
    setStatus("\u672A\u8FDE\u5C40\u57DF\u7F51\uFF0C\u65E0\u6CD5\u53D1\u9001", "err");
    return;
  }
  if (!p.pending.length) return;

  p.running = true;
  // New session if idle start
  if (!p.t0) {
    p.t0 = Date.now();
    p.done = 0;
    p.ok = 0;
    p.fail = 0;
    p.cancelledCount = 0;
  }
  updateSendProgressUi("\u5F00\u59CB\u53D1\u9001\u2026");
  renderQueue();

  try {
    while (p.pending.length > 0) {
      if (!lanOk) {
        setStatus("\u7F51\u7EDC\u4E2D\u65AD\uFF0C\u5269\u4F59 " + p.pending.length + " \u6761\u4ECD\u5728\u5F85\u53D1\u9001", "err");
        break;
      }
      var id = p.pending.shift();
      if (p.cancelled[id]) {
        delete p.cancelled[id];
        p.cancelledCount++;
        p.done++;
        p.activeId = null;
        updateSendProgressUi();
        renderQueue();
        continue;
      }
      p.activeId = id;
      renderQueue();

      var all = await storeAll("queue");
      var it = null;
      for (var i = 0; i < all.length; i++) {
        if (all[i].id === id) { it = all[i]; break; }
      }
      if (p.cancelled[id]) {
        delete p.cancelled[id];
        p.cancelledCount++;
        p.done++;
        p.activeId = null;
        updateSendProgressUi();
        renderQueue();
        continue;
      }
      if (!it) {
        // Already gone from cache (sent or deleted) \u2014 do NOT count as fail
        p.done++;
        p.activeId = null;
        updateSendProgressUi();
        continue;
      }

      var label = (it.title || it.fileName || it.type || "\u6761\u76EE").toString().slice(0, 28);
      var totalNow = pipelineTotal(p);
      showSendProgress(
        p.done,
        Math.max(totalNow, 1),
        "\u6B63\u5728\u53D1\u9001 " + (p.done + 1) + "/" + totalNow + " \xB7 " + label,
        true
      );
      setStatus("\u53D1\u9001\u4E2D\u2026 " + (p.done + 1) + "/" + totalNow, "ok");

      var sentOk = false;
      var errMsg = "";
      try {
        await sendOne(it);
        sentOk = true;
      } catch (e) {
        errMsg = String(e && e.message || e || "");
      }
      // if cancelled during flight, prefer cancel over fail when still in cache
      if (p.cancelled[id]) {
        delete p.cancelled[id];
        p.cancelledCount++;
        p.done++;
        p.activeId = null;
        updateSendProgressUi();
        renderQueue();
        continue;
      }
      if (sentOk) {
        try { await storeDel("queue", id); } catch (e2) {}
        p.ok++;
      } else {
        p.fail++;
        setStatus("\u53D1\u9001\u5931\u8D25\uFF1A" + errMsg, "err");
      }
      p.done++;
      p.activeId = null;
      updateSendProgressUi();
      renderQueue();
    }
  } finally {
    p.running = false;
    p.activeId = null;
    var finalMsg = "\u53D1\u9001\u5B8C\u6210\uFF1A\u6210\u529F " + p.ok +
      (p.fail ? "\uFF0C\u5931\u8D25 " + p.fail : "") +
      (p.cancelledCount ? "\uFF0C\u53D6\u6D88 " + p.cancelledCount : "");
    if (p.pending.length) {
      finalMsg = "\u8FDB\u884C\u4E2D\u65AD\uFF1A\u6210\u529F " + p.ok +
        (p.fail ? "\uFF0C\u5931\u8D25 " + p.fail : "") +
        "\uFF0C\u4ECD\u5269\u6392\u961F " + p.pending.length;
    }
    var st = "done";
    if (p.fail > 0 && p.ok === 0) st = "fail";
    else if (p.fail > 0) st = "done";
    if (p.pending.length) st = null;
    showSendProgress(p.done, Math.max(pipelineTotal(p), p.done, 1), finalMsg, false, st);
    setStatus(finalMsg, p.ok > 0 ? "ok" : (p.fail ? "err" : "ok"));
    renderQueue();
    refreshRecent();
    if (!p.pending.length) {
      setTimeout(function() {
        var q = ensureSendPipe();
        if (!q.running && !q.pending.length) {
          hideSendProgress();
          q.done = 0;
          q.ok = 0;
          q.fail = 0;
          q.cancelledCount = 0;
          q.t0 = 0;
          q.cancelled = {};
        }
      }, 3500);
    } else if (lanOk) {
      // continue remaining
      void pumpSend();
    }
  }
}

function cancelSendIds(ids) {
  var p = ensureSendPipe();
  var n = 0;
  (ids || []).forEach(function(id) {
    if (!id) return;
    var idx = p.pending.indexOf(id);
    if (idx >= 0) {
      p.pending.splice(idx, 1);
      p.cancelledCount++;
      p.done++;
      n++;
      return;
    }
    if (p.activeId === id) {
      p.cancelled[id] = true;
      n++;
    }
  });
  if (!n) {
    setStatus("\u8BF7\u52FE\u9009\u300C\u6392\u961F\u4E2D\u300D\u7684\u6761\u76EE\u4EE5\u53D6\u6D88\uFF08\u53D1\u9001\u4E2D\u53EA\u80FD\u5C3D\u91CF\u6807\u8BB0\uFF09", "err");
    return;
  }
  updateSendProgressUi();
  renderQueue();
  setStatus("\u5DF2\u53D6\u6D88 " + n + " \u6761\u6392\u961F\uFF08\u4ECD\u5728\u5F85\u53D1\u9001\u5217\u8868\uFF0C\u53EF\u7A0D\u540E\u91CD\u53D1\uFF09", "ok");
}

function showSendProgress(done, total, label, indeterminate, state) {
  var wrap = document.getElementById("sendProgress");
  var bar = document.getElementById("sendProgressBar");
  var lab = document.getElementById("sendProgressLabel");
  if (!wrap || !bar || !lab) return;
  wrap.classList.add("show");
  lab.textContent = label || "";
  bar.classList.remove("indeterminate", "done", "fail");
  if (state === "done") bar.classList.add("done");
  if (state === "fail") bar.classList.add("fail");
  if (indeterminate && done < total) {
    bar.classList.add("indeterminate");
    bar.style.width = "40%";
  } else {
    var pct = total > 0 ? Math.round((done / total) * 100) : 0;
    if (pct > 100) pct = 100;
    bar.style.width = pct + "%";
  }
}

function hideSendProgress() {
  var wrap = document.getElementById("sendProgress");
  var bar = document.getElementById("sendProgressBar");
  if (wrap) wrap.classList.remove("show");
  if (bar) {
    bar.style.width = "0%";
    bar.classList.remove("indeterminate", "done", "fail");
  }
}

function selectedFrom(listId) {
  return Array.from(document.querySelectorAll("#" + listId + " input[type=checkbox]:checked")).map(function(el) {
    return el.getAttribute("data-id");
  }).filter(function(id) {
    return id && !isInSendPipeline(id);
  });
}

function setAllChecks(listId, checked) {
  document.querySelectorAll("#" + listId + " input[type=checkbox]").forEach(function(el) {
    if (el.disabled) return;
    // for queue: only free items when selecting for send
    var id = el.getAttribute("data-id");
    if (listId === "queue" && checked && isInSendPipeline(id)) return;
    el.checked = !!checked;
  });
}

async function renderQueue() {
  var items = (await storeAll("queue")).sort(function(a,b){return (b.createdAt||0)-(a.createdAt||0);});
  var ul = document.getElementById("queue");
  ul.innerHTML = "";
  if (!items.length) {
    ul.innerHTML = "<li class='meta'>\u6682\u65E0\u5F85\u53D1\u9001\u5185\u5BB9</li>";
    return;
  }
  var p = window.__sendPipe;
  items.forEach(function(it) {
    var li = document.createElement("li");
    var label = it.type + " \xB7 " + esc(it.title || it.fileName || it.text || "").slice(0, 60);
    var when = it.createdAt ? new Date(it.createdAt).toLocaleString() : "";
    var inPipe = isInSendPipeline(it.id);
    var isActive = p && p.activeId === it.id;
    var badge = "";
    var dis = "";
    var rowCls = "item-row";
    if (isActive) {
      badge = "<span class='badge badge-send'>\u53D1\u9001\u4E2D</span>";
      rowCls += " sending";
    } else if (inPipe) {
      badge = "<span class='badge badge-wait'>\u6392\u961F\u4E2D</span>";
      rowCls += " sending";
    }
    // queued/active can be checked for cancel; free for send
    li.innerHTML = "<div class='" + rowCls + "'><input type='checkbox' data-id='" + esc(it.id) + "'" + dis + "/><div><strong>" +
      label + "</strong>" + badge + "<div class='meta'>\u505A\u6210 " + when + " \xB7 \u53D1\u9001\u540E\u7535\u8111\u5C06\u4F7F\u7528\u6B64\u65F6\u95F4</div></div></div>";
    ul.appendChild(li);
  });
}

async function renderTrash() {
  await purgeExpiredTrash();
  var items = (await storeAll("trash")).sort(function(a,b){return (b.trashedAt||0)-(a.trashedAt||0);});
  var ul = document.getElementById("trash");
  ul.innerHTML = "";
  if (!items.length) {
    ul.innerHTML = "<li class='meta'>\u5783\u573E\u7BB1\u4E3A\u7A7A</li>";
    return;
  }
  items.forEach(function(it) {
    var left = Math.max(0, TRASH_MS - (Date.now() - (it.trashedAt || 0)));
    var days = Math.ceil(left / (24*60*60*1000));
    var li = document.createElement("li");
    li.innerHTML = "<div class='item-row'><input type='checkbox' data-id='" + esc(it.id) + "'/><div><strong>" +
      esc(it.type + " \xB7 " + (it.title || it.fileName || "")) +
      "</strong><div class='meta'>\u5269\u4F59\u7EA6 " + days + " \u5929 \xB7 " + new Date(it.trashedAt||0).toLocaleString() + "</div></div></div>";
    ul.appendChild(li);
  });
}

document.getElementById("btnSelAll").onclick = function() { setAllChecks("queue", true); };
document.getElementById("btnSelNone").onclick = function() { setAllChecks("queue", false); };
document.getElementById("btnTrashSelAll").onclick = function() { setAllChecks("trash", true); };
document.getElementById("btnTrashSelNone").onclick = function() { setAllChecks("trash", false); };

document.getElementById("btnSendSel").onclick = function() {
  void sendIds(selectedFrom("queue"));
};
document.getElementById("btnSendAll").onclick = function() {
  void (async function() {
    var items = await storeAll("queue");
    var ids = items.map(function(x){ return x.id; }).filter(function(id){
      return !isInSendPipeline(id);
    });
    await sendIds(ids);
  })();
};
document.getElementById("btnCancelSel").onclick = function() {
  var ids = Array.from(document.querySelectorAll("#queue input[type=checkbox]:checked")).map(function(el) {
    return el.getAttribute("data-id");
  }).filter(Boolean);
  cancelSendIds(ids);
};
document.getElementById("btnDelSel").onclick = async function() {
  var ids = selectedFrom("queue");
  var all = await storeAll("queue");
  var byId = {};
  all.forEach(function(x){ byId[x.id] = x; });
  for (var i = 0; i < ids.length; i++) {
    var it = byId[ids[i]];
    if (!it) continue;
    it.trashedAt = Date.now();
    await storePut("trash", it);
    await storeDel("queue", ids[i]);
  }
  renderQueue();
  setStatus("\u5DF2\u79FB\u5165\u5783\u573E\u7BB1", "ok");
};
document.getElementById("btnRestore").onclick = async function() {
  var ids = selectedFrom("trash");
  var all = await storeAll("trash");
  var byId = {};
  all.forEach(function(x){ byId[x.id] = x; });
  for (var i = 0; i < ids.length; i++) {
    var it = byId[ids[i]];
    if (!it) continue;
    delete it.trashedAt;
    await storePut("queue", it);
    await storeDel("trash", ids[i]);
  }
  renderTrash();
  setStatus("\u5DF2\u6062\u590D\u5230\u5F85\u53D1\u9001", "ok");
};
document.getElementById("btnPurge").onclick = async function() {
  var ids = selectedFrom("trash");
  for (var i = 0; i < ids.length; i++) await storeDel("trash", ids[i]);
  renderTrash();
};
document.getElementById("btnEmpty").onclick = async function() {
  if (!confirm("\u6E05\u7A7A\u5783\u573E\u7BB1\uFF1F\u4E0D\u53EF\u6062\u590D")) return;
  var items = await storeAll("trash");
  for (var i = 0; i < items.length; i++) await storeDel("trash", items[i].id);
  renderTrash();
};

